    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placing the item
    let mut score = post_residual as f64;

    // 1. Quadratic waste penalty – discourage large gaps
    score += (post_residual as f64).powi(2) * 0.00012;

    // 2. Tight‑fit bonus – reward bins that leave very little space
