        score += ((residual_ratio - 0.4).powi(2)) * 1200.0 * time_factor;
    } else if residual_ratio < 0.05 {
        // very tight fit
        score -= ((0.05 - residual_ratio).powi(2)) * 600.0;
    }

    // Reward closeness to the stream‑wide mean residual
    let mean_diff = (mean_residual - post_residual as f64).abs();
    score += mean_diff * 1.2;

    // Penalise many open bins (logarithmic scaling)
    let open_log = (open_bins_count as f64 + 1.0).ln();
    score += open_log * 0.4;

    // If the bin is empty, decide whether a new bin is preferable
    if bin_residual == bin_capacity {
        if item_size > (bin_capacity * 9) / 10 {
            // very large item – favour a fresh bin
            score -= 28.0;
        } else if fitting_bins_count > 2 {
            // many options – discourage opening a new bin
            score += 32.0;
        } else {
            // few options – slight preference for new bin
            score -= 7.0;
        }
    }

    // Look‑ahead: consider the next item
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item would overflow the bin
            score += (next_item_size as f64 - post_residual as f64) * 9.0;
        } else {
            // current bin likely still useful
            score -= 4.0;
        }
    }

    // Penalise too many candidate bins
    if fitting_bins_count > 4 {
        score += ((fitting_bins_count as f64) - 3.0) * 2.5;
    }

    // Reward placing a very large item close to capacity
    if item_size > (bin_capacity * 19) / 20 {
        score -= 12.0;
    }

    // End‑of‑stream tightening: encourage packing tighter when few items remain
    if step_index > (total_items * 3) / 4 && post_residual > mean_residual as u32 {
        score += 18.0;
    }

    // Periodic diversification: every 17th step slightly lower score
    if step_index % 17 == 0 {
        score -= 3.0;
    }

    // Extra penalty if open bins explode relative to stream length
    if open_bins_count as f64 > (total_items as f64) * 0.015 {
        score += 9.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised stream progress
    let progress = step_index as f64 / (total_items as f64 + 1.0);

    // Ratios describing the bin state
    let residual_ratio = post_residual as f64 / (bin_capacity as f64 + 1.0);
    let filled_ratio = (bin_residual - post_residual) as f64 / (bin_capacity as f64 + 1.0);

    // How many open bins can accommodate the item
    let fit_ratio = if open_bins_count > 0 {
        (fitting_bins_count as f64) / (open_bins_count as f64)
    } else {
        1.0
    };

    // Open‑bin density in the stream
    let open_density = open_bins_count as f64 / (total_items as f64 + 1.0);

    // ---- Core scoring terms ----
    // 1. Penalise large residual after placement, but reduce penalty later in the stream
    let mut score = residual_ratio * (1.0 - 0.4 * progress);

    // 2. Reward a tight fit: subtract a term proportional to the space left by the item
    score -= (bin_residual - item_size) as f64 / (bin_capacity as f64 + 1.0) * 2.0;

    // 3. Prefer bins that many other items can also fit into
    score -= fit_ratio.powi(2) * 1.5;

    // 4. Penalise having a large pool of open bins (encourages packing)
    score += open_density.powi(2) * 5.0 / (open_bins_count as f64 + 1.0);

    // 5. Penalise deviation from the mean residual across all open bins
    score += (residual_ratio - mean_residual).abs() * 2.0;

    // 6. Look‑ahead: if the next item will not fit in this bin, add a cost
    if next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64
            / (bin_capacity as f64 + 1.0);
        score += diff.powi(2) * progress * 3.0 / (next_item_size as f64 + 1.0);
    }

    // 7. Special handling for a brand‑new empty bin: add a high baseline cost
    if bin_residual == bin_capacity {
        score += 5.0 - 2.0 * progress;
    }

    // Ensure the score is not negative (lower scores are better)
    if score < 0.0 {
        score = 0.0;
    }
    score
}

